/**
 * Exact Decimal Token Parser.
 *
 * Converts a decimal string representation (e.g. "0.07", "-0.1428571428571428571")
 * directly into an exact scaled BigInt without passing through binary
 * floating-point representation (IEEE 754 float64).
 */
export function parseExactDecimalToken(token: string | number, scalePower: number = 19): bigint {
  let str = typeof token === "number" ? token.toString() : String(token);
  str = str.trim();
  if (!str) throw new Error("Empty decimal token");
  const isNeg = str.startsWith("-");
  if (isNeg || str.startsWith("+")) {
    str = str.slice(1);
  }

  // Handle scientific exponent notation if present (e.g. 1e-5, 2.5e-3)
  if (str.includes("e") || str.includes("E")) {
    const parts = str.split(/[eE]/);
    if (parts.length !== 2) throw new Error(`Malformed exponent in decimal token: "${token}"`);
    const [mantissa, expStr] = parts;
    const exp = parseInt(expStr || "", 10);
    if (isNaN(exp)) throw new Error(`Invalid exponent in decimal token: "${token}"`);
    const [mInt = "0", mFrac = ""] = (mantissa || "").split(".");
    if (exp < 0) {
      const shift = -exp;
      const fullFrac = "0".repeat(shift - 1) + (mInt || "0") + mFrac;
      str = "0." + fullFrac;
    } else if (exp > 0) {
      if (mFrac.length <= exp) {
        str = (mInt || "0") + mFrac + "0".repeat(exp - mFrac.length);
      } else {
        str = (mInt || "0") + mFrac.slice(0, exp) + "." + mFrac.slice(exp);
      }
    } else {
      str = mantissa || "0";
    }
  }

  const dotParts = str.split(".");
  if (dotParts.length > 2)
    throw new Error(`Malformed decimal token with multiple dots: "${token}"`);
  const [intStr = "0", fracStr = ""] = dotParts;
  if (!/^\d*$/.test(intStr) || !/^\d*$/.test(fracStr)) {
    throw new Error(`Malformed decimal token with non-digit characters: "${token}"`);
  }

  if (fracStr.length > scalePower) {
    const excess = fracStr.slice(scalePower);
    if (/[^0]/.test(excess)) {
      throw new Error(`Unsupported fractional precision beyond scale 10^${scalePower}: "${token}"`);
    }
  }

  const scale = 10n ** BigInt(scalePower);
  const intVal = BigInt(intStr || "0") * scale;
  const fracVal = BigInt(fracStr.slice(0, scalePower).padEnd(scalePower, "0") || "0");

  const total = intVal + fracVal;
  return isNeg ? -total : total;
}

/**
 * JSON parser that preserves raw numeric tokens as exact decimal strings
 * instead of converting them to IEEE 754 float64 binary numbers.
 */
export function parseJsonWithExactDecimals(text: string): unknown {
  let pos = 0;

  function skipWhitespace(): void {
    while (
      pos < text.length &&
      (text[pos] === " " || text[pos] === "\t" || text[pos] === "\n" || text[pos] === "\r")
    ) {
      pos++;
    }
  }

  function parseValue(): unknown {
    skipWhitespace();
    if (pos >= text.length) throw new Error("Unexpected end of JSON input");
    const ch = text[pos]!;
    if (ch === "{") return parseObject();
    if (ch === "[") return parseArray();
    if (ch === '"') return parseString();
    if (ch === "t" && text.startsWith("true", pos)) {
      pos += 4;
      return true;
    }
    if (ch === "f" && text.startsWith("false", pos)) {
      pos += 5;
      return false;
    }
    if (ch === "n" && text.startsWith("null", pos)) {
      pos += 4;
      return null;
    }
    if (ch === "-" || (ch >= "0" && ch <= "9")) return parseNumberString();
    throw new Error(`Unexpected character at ${pos}: ${ch}`);
  }

  function parseString(): string {
    pos++; // skip opening quote
    let result = "";
    while (pos < text.length) {
      const ch = text[pos++];
      if (ch === '"') return result;
      if (ch === "\\") {
        const esc = text[pos++];
        if (esc === '"') result += '"';
        else if (esc === "\\") result += "\\";
        else if (esc === "/") result += "/";
        else if (esc === "b") result += "\b";
        else if (esc === "f") result += "\f";
        else if (esc === "n") result += "\n";
        else if (esc === "r") result += "\r";
        else if (esc === "t") result += "\t";
        else if (esc === "u") {
          const hex = text.slice(pos, pos + 4);
          result += String.fromCharCode(parseInt(hex, 16));
          pos += 4;
        }
      } else {
        result += ch;
      }
    }
    throw new Error("Unterminated string");
  }

  function parseNumberString(): string {
    const start = pos;
    if (text[pos] === "-") pos++;
    while (pos < text.length && text[pos]! >= "0" && text[pos]! <= "9") pos++;
    if (pos < text.length && text[pos] === ".") {
      pos++;
      while (pos < text.length && text[pos]! >= "0" && text[pos]! <= "9") pos++;
    }
    if (pos < text.length && (text[pos] === "e" || text[pos] === "E")) {
      pos++;
      if (pos < text.length && (text[pos] === "+" || text[pos] === "-")) pos++;
      while (pos < text.length && text[pos]! >= "0" && text[pos]! <= "9") pos++;
    }
    return text.slice(start, pos);
  }

  function parseArray(): unknown[] {
    pos++; // skip [
    const arr: unknown[] = [];
    skipWhitespace();
    if (pos < text.length && text[pos] === "]") {
      pos++;
      return arr;
    }
    while (pos < text.length) {
      arr.push(parseValue());
      skipWhitespace();
      if (text[pos] === "]") {
        pos++;
        return arr;
      }
      if (text[pos] === ",") {
        pos++;
      } else {
        throw new Error(`Expected , or ] at ${pos}`);
      }
    }
    throw new Error("Unterminated array");
  }

  function parseObject(): Record<string, unknown> {
    pos++; // skip {
    const obj: Record<string, unknown> = {};
    skipWhitespace();
    if (pos < text.length && text[pos] === "}") {
      pos++;
      return obj;
    }
    while (pos < text.length) {
      skipWhitespace();
      if (text[pos] !== '"') throw new Error(`Expected string key at ${pos}`);
      const key = parseString();
      skipWhitespace();
      if (text[pos] !== ":") throw new Error(`Expected : at ${pos}`);
      pos++;
      obj[key] = parseValue();
      skipWhitespace();
      if (text[pos] === "}") {
        pos++;
        return obj;
      }
      if (text[pos] === ",") {
        pos++;
      } else {
        throw new Error(`Expected , or } at ${pos}`);
      }
    }
    throw new Error("Unterminated object");
  }

  return parseValue();
}

export interface TorchLeanSource {
  repository: string;
  commit: string;
  path: string;
  sha256: string;
  leanToolchain: string;
}

export interface TorchLeanArchitectureNode {
  id: string;
  op: "input" | "linear" | "logits" | "margin-check";
  label: string;
  detail: string;
  shape: number[];
}

export interface TorchLeanMarginExample {
  id: number;
  label: number;
  prediction: number;
  lower: number[];
  upper: number[];
  certified: boolean;
}

export interface TorchLeanMarginSnapshot {
  format: "prooflens_torchlean_margin_snapshot_v0_1";
  source: TorchLeanSource;
  model: {
    id: string;
    title: string;
    architecture: TorchLeanArchitectureNode[];
  };
  report: {
    upstreamFormat: "robust_margin_cert_v0_1";
    norm: "linf";
    method: string;
    epsilon: number;
    inputDimension: number;
    classCount: number;
    summary: { examples: number; nominalOk: number; certifiedOk: number };
  };
  examples: TorchLeanMarginExample[];
  upstreamBoundary: {
    marginReportCheck: "not-replayed" | "replayed";
    enclosureProof: "not-established" | "established-by-imported-kernel-witness";
  };
}

export interface TorchLeanEnclosureBinding {
  sourceRepository: string;
  sourceCommit: string;
  sourcePath: string;
  sourceSha256: string;
  modelId: string;
  norm: "linf";
  method: string;
  epsilon: number;
  inputDimension: number;
  classCount: number;
  exampleIds: number[];
}

/**
 * Serializable request emitted before any enclosure proof exists. It is a
 * specification of the evidence ProofLens needs, never evidence by itself.
 */
export interface TorchLeanEnclosureRequest {
  format: typeof TORCHLEAN_ENCLOSURE_REQUEST_FORMAT;
  binding: TorchLeanEnclosureBinding;
  requiredClaim: "the listed logit intervals enclose the pinned model on the stated input regions";
  acceptedAuthority: "lean-kernel";
  note: string;
}

/** A receipt can name a theorem, but imported JSON cannot mint its witness. */
export interface TorchLeanEnclosureReceipt {
  format: typeof TORCHLEAN_ENCLOSURE_RECEIPT_FORMAT;
  binding: TorchLeanEnclosureBinding;
  proof: {
    authority: "lean-kernel";
    protocol: "prooflens-torchlean-enclosure-v0.1";
    declaration: string;
    module: string;
    statement: string;
    formalIrSha256: string;
  };
}

export interface TrustedTorchLeanFormalIR {
  document: FormalIRDocument;
  sha256: string;
}

export interface TorchLeanApplicationNode {
  id: number;
  op: string;
  parents: number[];
  shape: string;
}

export interface TorchLeanApplicationAudit {
  format: "prooflens_torchlean_application_audit_v0_1";
  source: { repository: string; commit: string; leanToolchain: string };
  artifacts: Record<string, { path: string; sha256: string }>;
  replay: {
    byteForByteMatch: boolean;
    sha256: string;
    examples: number;
    nominalOk: number;
    certifiedOk: number;
  };
  lowering: { inputId: number; outputId: number; nodes: TorchLeanApplicationNode[] };
  theorem: {
    declaration: string;
    supportedOps: string[];
    unsupportedOpsObserved: string[];
  };
  arithmetic: {
    reportProducer: string;
    theoremSemantics: string;
    outwardRoundingBridge: boolean;
  };
  conclusion: { status: "blocked" | "verified"; reason: string };
}

export type TorchLeanApplicationGateStatus =
  "matched" | "blocked" | "owed" | "verified" | "not-used";

export interface TorchLeanApplicationGate {
  id: "artifacts" | "replay" | "topology" | "operations" | "inputs" | "rounding";
  label: string;
  status: TorchLeanApplicationGateStatus;
  description: string;
}

export interface TorchLeanApplicationEvidence {
  status: "blocked" | "verified";
  nodes: Array<TorchLeanApplicationNode & { supported: boolean }>;
  gates: TorchLeanApplicationGate[];
  reason: string;
}

function verifiedDirectApplication(
  application: TorchLeanApplicationEvidence,
): TorchLeanApplicationEvidence {
  return {
    ...application,
    status: "verified",
    gates: application.gates.map((gate) => {
      if (gate.id === "operations") {
        return {
          ...gate,
          status: "not-used",
          label: "Generic graph path",
          description:
            "The exact linear certificate bypasses the unsupported reshape and concat wrappers.",
        };
      }
      if (gate.id === "inputs") {
        return {
          ...gate,
          status: "verified",
          description:
            "The theorem covers every 64-value input inside all 360 exact source perturbation boxes.",
        };
      }
      if (gate.id === "rounding") {
        return {
          ...gate,
          status: "verified",
          label: "Exact-real bounds",
          description:
            "The certificate uses exact decimal rationals and exact lower/upper sums, not binary64 endpoints.",
        };
      }
      return gate;
    }),
    reason:
      "A hash-bound zero-sorry Lean theorem directly encloses the pinned linear model on all 360 displayed input regions using exact-real arithmetic.",
  };
}

export const TORCHLEAN_IBP_SOUNDNESS_PIN = {
  repository: "https://github.com/lean-dojo/TorchLean",
  commit: "12f5c651f03b3890ec012d0a6bb45e3ea698c8d3",
  toolchain: "4.33.0",
  module: "NN.MLTheory.CROWN.Proofs.GraphRunibpEndToEnd",
  declaration: "NN.MLTheory.CROWN.Graph.CertSoundness.runIBP?_encloses_evalGraphRec",
  formalIrSha256: "3aa4f293011dd4dcd30a6d280c8e2a63f7524c3aed7376254e8a1016f6800ae4",
  statement: `∀ (g : NN.MLTheory.CROWN.Graph) (ps : NN.MLTheory.CROWN.Graph.ParamStore ℝ)
  (inputs : Std.HashMap ℕ NN.MLTheory.CROWN.Graph.CertSoundness.Val),
  NN.MLTheory.CROWN.Graph.CertSoundness.TopoSorted g →
    NN.MLTheory.CROWN.Graph.CertSoundness.Supported g →
      NN.MLTheory.CROWN.Graph.CertSoundness.InputsEnclosed g ps inputs →
        ∀ id < g.nodes.size,
          match (NN.MLTheory.CROWN.Graph.CertSoundness.runIBP? g ps)[id]!,
            (NN.MLTheory.CROWN.Graph.CertSoundness.evalGraphRec g ps inputs)[id]! with
          | some B, some v => NN.MLTheory.CROWN.Graph.CertSoundness.EnclosesBox B v
          | x, x_1 => True`,
} as const;

export interface TorchLeanSoundnessPremise {
  id: "artifact-binding" | "topological-order" | "supported-operations" | "input-enclosure";
  label: string;
  status: "owed";
  description: string;
}

export interface TorchLeanSoundnessEvidence {
  status: EpistemicStatus;
  verification: "formal-ir-missing" | "formal-ir-mismatch" | "kernel-theorem-verified";
  reason: string;
  theorem: typeof TORCHLEAN_IBP_SOUNDNESS_PIN;
  premises: TorchLeanSoundnessPremise[];
  provenance: Provenance;
}

export interface TorchLeanEnclosureEvidence {
  status: EpistemicStatus;
  verification: "receipt-missing" | "receipt-mismatch" | "kernel-witness-matched";
  reason: string;
  request: TorchLeanEnclosureRequest;
  receipt?: TorchLeanEnclosureReceipt;
  provenance: Provenance;
}

export interface TorchLeanClassInterval {
  classId: number;
  lower: number;
  upper: number;
  isLabel: boolean;
  isStrongestCompetitor: boolean;
}

export interface TorchLeanExampleScene {
  id: number;
  label: number;
  prediction: number;
  certified: boolean;
  computedCertified: boolean;
  labelFloor: number;
  competitorCeiling: number;
  competitorClass: number;
  margin: number;
  intervals: TorchLeanClassInterval[];
  explanation: string;
  intervalAuthority: "upstream-binary64-report" | "lean-exact-outward-certificate";
}

